"""唯一异常类型：本包所有无效输入均抛出 ABITypeError。"""


class ABITypeError(ValueError):
    """无效的 ABI 类型字符串或类型对象。"""

"""不可变的 ABI 类型对象。

类型对象分三种，可通过类区分：
- ElementaryType：基础类型（uintM/intM/address/bool/string/bytes/bytesM）
- ArrayType：数组类型（T[] 动态数组、T[n] 定长数组）
- TupleType：元组类型（(T1,T2,...)，允许空元组）

所有对象均为 frozen dataclass，构造时即完成自洽校验，包括
从基础类型向外最多 MAX_TYPE_DEPTH 层的嵌套上限。
"""

from __future__ import annotations

from dataclasses import dataclass, field

from ._exceptions import ABITypeError

#: 从基础类型向外计数的最大嵌套层数（基础类型自身计第 1 层）。
MAX_TYPE_DEPTH = 128

_UINT = "uint"
_INT = "int"
_ADDRESS = "address"
_BOOL = "bool"
_STRING = "string"
_BYTES = "bytes"


@dataclass(frozen=True)
class ABIType:
    """所有 ABI 类型对象的抽象基类。"""

    @property
    def depth(self) -> int:
        """从基础类型向外的层数，基础类型为 1。"""
        raise NotImplementedError


@dataclass(frozen=True)
class ElementaryType(ABIType):
    """基础类型。

    kind 取值：
    - ``"uint"`` / ``"int"``：bit_size 为 8..256 的 8 的倍数
    - ``"address"`` / ``"bool"`` / ``"string"``：两个宽度均为 None
    - ``"bytes"``：byte_size 为 None 表示动态 bytes，否则为 1..32
    """

    kind: str
    bit_size: int | None = None
    byte_size: int | None = None

    def __post_init__(self) -> None:
        kind = self.kind
        if kind in (_UINT, _INT):
            if not isinstance(self.bit_size, int) or isinstance(self.bit_size, bool):
                raise ABITypeError(f"{kind} 类型必须给出整数位宽")
            if self.byte_size is not None:
                raise ABITypeError(f"{kind} 类型不能带有字节宽度")
            if not (8 <= self.bit_size <= 256 and self.bit_size % 8 == 0):
                raise ABITypeError(
                    f"{kind} 的位宽必须是 8 到 256 之间 8 的倍数，得到 {self.bit_size}"
                )
        elif kind in (_ADDRESS, _BOOL, _STRING, _BYTES):
            if self.bit_size is not None:
                raise ABITypeError(f"{kind} 类型不能带有整数位宽")
            if kind == _BYTES and self.byte_size is not None:
                if (
                    isinstance(self.byte_size, bool)
                    or not isinstance(self.byte_size, int)
                    or not (1 <= self.byte_size <= 32)
                ):
                    raise ABITypeError(
                        f"bytesM 的 M 必须在 1 到 32 之间，得到 {self.byte_size!r}"
                    )
            elif self.byte_size is not None:
                raise ABITypeError(f"{kind} 类型不能带有字节宽度")
        else:
            raise ABITypeError(f"未知的基础类型：{kind!r}")

    @property
    def depth(self) -> int:
        return 1


@dataclass(frozen=True)
class ArrayType(ABIType):
    """数组类型；length 为 None 表示动态数组 T[]，否则为定长数组 T[n]。"""

    element_type: ABIType
    length: int | None = None

    def __post_init__(self) -> None:
        if not isinstance(self.element_type, ABIType):
            raise ABITypeError("数组元素类型必须是 ABIType")
        if self.length is not None:
            if isinstance(self.length, bool) or not isinstance(self.length, int):
                raise ABITypeError(f"数组长度必须是正整数，得到 {self.length!r}")
            if self.length <= 0:
                raise ABITypeError(f"数组长度必须是正整数，得到 {self.length}")
        if self.depth > MAX_TYPE_DEPTH:
            raise ABITypeError(f"类型嵌套超过 {MAX_TYPE_DEPTH} 层")

    @property
    def depth(self) -> int:
        return self.element_type.depth + 1


@dataclass(frozen=True)
class TupleType(ABIType):
    """元组类型，components 按声明顺序保存各组成部分。"""

    components: tuple[ABIType, ...] = field(default=())

    def __post_init__(self) -> None:
        try:
            components = tuple(self.components)
        except TypeError as exc:
            raise ABITypeError("元组组成部分必须是 ABIType 序列") from exc
        for component in components:
            if not isinstance(component, ABIType):
                raise ABITypeError("元组组成部分必须是 ABIType")
        object.__setattr__(self, "components", components)
        if self.depth > MAX_TYPE_DEPTH:
            raise ABITypeError(f"类型嵌套超过 {MAX_TYPE_DEPTH} 层")

    @property
    def depth(self) -> int:
        return 1 + max((c.depth for c in self.components), default=0)

"""ABI 类型字符串的递归下降解析器。

语法（空白规则见下）::

    type       := elementary | tuple ，后接零个或多个数组后缀
    elementary := uintM | intM | address | bool | string | bytes | bytesM
    tuple      := '(' [type (',' type)*] ')'
    suffix     := '[]' | '[' [1-9][0-9]* ']'

空白（仅 ASCII 空白）只允许出现在：
1. 整个类型字符串的两端；
2. 元组中逗号的两侧。
其余位置的空白（类型词内部、括号内侧、数组语法内部等）一律报错。
输入必须完整解析，尾随任何非空白字符均报错。
"""

from __future__ import annotations

from ._exceptions import ABITypeError
from ._types import ABIType, ArrayType, ElementaryType, TupleType

_WHITESPACE = " \t\n\r\f\v"

#: 解析器括号递归的安全上限：语义嵌套上限（128 层）由类型对象构造时
#: 检查；此阈值仅用于在触及 Python 递归限制（实测约 500 层括号）前抛出
#: ABITypeError，远低于递归上限且高于任何合法输入。
_RECURSION_SAFETY_LIMIT = 200


class _Parser:
    def __init__(self, text: str) -> None:
        self._text = text
        self._pos = 0
        self._len = len(text)
        self._tuple_depth = 0

    def parse(self) -> ABIType:
        self._skip_whitespace()
        result = self._parse_type()
        self._skip_whitespace()
        if self._pos != self._len:
            raise self._error("存在无法解析的尾随内容")
        return result

    # ---- 通用构件 -------------------------------------------------------

    def _error(self, message: str) -> ABITypeError:
        return ABITypeError(f"无效的 ABI 类型 {self._text!r}（位置 {self._pos}）：{message}")

    def _skip_whitespace(self) -> None:
        text = self._text
        while self._pos < self._len and text[self._pos] in _WHITESPACE:
            self._pos += 1

    def _peek(self) -> str | None:
        if self._pos >= self._len:
            return None
        return self._text[self._pos]

    # ---- 类型 -----------------------------------------------------------

    def _parse_type(self) -> ABIType:
        ch = self._peek()
        if ch is None:
            raise self._error("类型不完整")
        if ch == "(":
            head: ABIType = self._parse_tuple()
        elif ch.isascii() and ch.isalpha():
            head = self._parse_elementary()
        else:
            raise self._error("此处应为基础类型或元组")
        return self._parse_suffixes(head)

    def _parse_elementary(self) -> ElementaryType:
        text = self._text
        start = self._pos
        while self._pos < self._len:
            ch = text[self._pos]
            if ch.isascii() and ch.isalnum():
                self._pos += 1
            else:
                break
        word = text[start:self._pos]
        return self._classify(word)

    def _classify(self, word: str) -> ElementaryType:
        if word in ("address", "bool", "string"):
            return ElementaryType(word)
        if word == "bytes":
            return ElementaryType("bytes")
        if word.startswith("bytes") and len(word) > len("bytes"):
            return self._sized_bytes(word)
        if word.startswith("uint") or word.startswith("int"):
            return self._sized_integer(word)
        raise self._error(f"不是合法的基础类型：{word!r}")

    def _digits_suffix(self, word: str, prefix: str) -> str:
        digits = word[len(prefix):]
        if not digits or not digits.isascii() or not digits.isdigit():
            raise self._error(f"不是合法的基础类型：{word!r}")
        if len(digits) > 1 and digits[0] == "0":
            raise self._error(f"类型宽度不允许前导零：{word!r}")
        return digits

    def _sized_integer(self, word: str) -> ElementaryType:
        if word.startswith("uint"):
            prefix, kind = "uint", "uint"
        else:
            prefix, kind = "int", "int"
        digits = self._digits_suffix(word, prefix)
        try:
            return ElementaryType(kind, bit_size=int(digits))
        except ABITypeError:
            # 规范化错误信息：重新抛出由本解析器生成的错误
            raise self._error(
                f"{kind} 的位宽必须是 8 到 256 之间 8 的倍数，得到 {digits}"
            ) from None

    def _sized_bytes(self, word: str) -> ElementaryType:
        digits = self._digits_suffix(word, "bytes")
        try:
            return ElementaryType("bytes", byte_size=int(digits))
        except ABITypeError:
            raise self._error(f"bytesM 的 M 必须在 1 到 32 之间，得到 {digits}") from None

    def _parse_tuple(self) -> TupleType:
        # 调用前当前字符为 '('；括号内侧不允许空白。
        self._pos += 1
        self._tuple_depth += 1
        # 语义嵌套上限由类型对象构造检查；此处仅在触及 Python 递归限制
        # 前拦截过深（或大量未闭合）的括号，保证唯一异常约定。
        if self._tuple_depth > _RECURSION_SAFETY_LIMIT:
            self._tuple_depth -= 1
            raise self._error("类型嵌套过深或括号未正确闭合")
        try:
            if self._peek() == ")":
                self._pos += 1
                return TupleType(())
            components: list[ABIType] = []
            while True:
                components.append(self._parse_type())
                # 逗号左侧允许 ASCII 空白；但 ')' 内侧不允许，因此先记录
                # 是否跳过了空白，若空白后直接是 ')' 则属非法。
                anchor = self._pos
                self._skip_whitespace()
                had_whitespace = self._pos != anchor
                ch = self._peek()
                if ch == ",":
                    self._pos += 1
                    # 逗号右侧允许 ASCII 空白。
                    self._skip_whitespace()
                    if self._peek() in (None, ",", ")"):
                        raise self._error("逗号后缺少类型")
                    continue
                if ch == ")":
                    if had_whitespace:
                        raise self._error("元组 ')' 内侧不允许空白")
                    self._pos += 1
                    return TupleType(tuple(components))
                raise self._error("元组中应为 ',' 或 ')'")
        finally:
            self._tuple_depth -= 1

    def _parse_suffixes(self, head: ABIType) -> ABIType:
        current = head
        while self._peek() == "[":
            self._pos += 1
            ch = self._peek()
            if ch is None:
                raise self._error("数组后缀不完整")
            if ch == "]":
                self._pos += 1
                current = ArrayType(current)
                continue
            # 定长数组：只接受 [1-9][0-9]*，拒绝 0 与前导零。
            if not (ch.isascii() and ch.isdigit()) or ch == "0":
                raise self._error("数组长度必须是无前导零的正整数")
            start = self._pos
            while True:
                ch = self._peek()
                if ch is not None and ch.isascii() and ch.isdigit():
                    self._pos += 1
                    continue
                break
            length = int(self._text[start:self._pos])
            if self._peek() != "]":
                raise self._error("数组后缀缺少 ']'")
            self._pos += 1
            current = ArrayType(current, length)
        return current


def parse_abi_type(type_string: str) -> ABIType:
    """解析 ABI 类型字符串，返回不可变类型对象。

    无效输入统一抛出 :class:`abi_kit.ABITypeError`。
    """
    if not isinstance(type_string, str):
        raise ABITypeError(f"ABI 类型必须是字符串，得到 {type(type_string).__name__}")
    if type_string == "":
        raise ABITypeError("无效的 ABI 类型 ''：类型为空")
    return _Parser(type_string).parse()

"""Solidity ABI 值层编解码（head/tail 规则）。

公开入口：
- encode_abi_value(abi_type, value) -> bytes
- decode_abi_value(abi_type, data) -> Python 值

编码布局遵循 Solidity ABI 规范：单个值的编码等同于只含该值的
一元元组编码——静态类型直接是其字编码，动态类型则先放一个
偏移字，尾部跟随实际内容。

值口径：整数为 int，bool 为 bool，string 为 str，bytes/bytesM 为
bytes，address 为小写 ``0x`` 加 40 位十六进制字符串，数组为 list，
元组为 tuple。所有值/编码/类型问题统一抛出 ABIValueError。
"""

from __future__ import annotations

from ._exceptions import ABIValueError
from ._types import ABIType, ArrayType, ElementaryType, TupleType

_WORD = 32
_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")

#: 元素编码尺寸为 0 的数组（如 ``()[]``）允许解码的最大长度，
#: 防止畸形长度字导致解码循环无法终止。
_ZERO_SIZE_ELEMENT_LIMIT = 1 << 20


# ---- 类型结构辅助 -------------------------------------------------------


def _is_dynamic(abi_type: ABIType) -> bool:
    if isinstance(abi_type, ElementaryType):
        return abi_type.kind == "string" or (
            abi_type.kind == "bytes" and abi_type.byte_size is None
        )
    if isinstance(abi_type, ArrayType):
        return abi_type.length is None or _is_dynamic(abi_type.element_type)
    if isinstance(abi_type, TupleType):
        return any(_is_dynamic(c) for c in abi_type.components)
    raise ABIValueError(f"不是合法的 ABI 类型对象：{abi_type!r}")


def _static_size(abi_type: ABIType) -> int:
    """静态类型在 head 区域占用的字节数；仅对静态类型调用。"""
    if isinstance(abi_type, ElementaryType):
        return _WORD
    if isinstance(abi_type, ArrayType):
        return abi_type.length * _static_size(abi_type.element_type)
    if isinstance(abi_type, TupleType):
        return sum(_static_size(c) for c in abi_type.components)
    raise ABIValueError(f"不是合法的 ABI 类型对象：{abi_type!r}")


def _check_type(abi_type: ABIType) -> None:
    if not isinstance(abi_type, ABIType):
        raise ABIValueError(f"不是合法的 ABI 类型对象：{abi_type!r}")


def _word(number: int) -> bytes:
    return number.to_bytes(_WORD, "big")


# ---- 编码 ---------------------------------------------------------------


def _check_int(value: object, type_desc: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int):
        raise ABIValueError(
            f"{type_desc} 的值必须是 int，得到 {type(value).__name__}"
        )
    return value


def _check_bytes(value: object, type_desc: str) -> bytes:
    if isinstance(value, (bytes, bytearray, memoryview)):
        return bytes(value)
    raise ABIValueError(
        f"{type_desc} 的值必须是 bytes 类型，得到 {type(value).__name__}"
    )


def _check_sequence(value: object, type_desc: str) -> list:
    if isinstance(value, (list, tuple)):
        return list(value)
    raise ABIValueError(
        f"{type_desc} 的值必须是 list 或 tuple，得到 {type(value).__name__}"
    )


def _encode_address(value: object) -> bytes:
    if not isinstance(value, str):
        raise ABIValueError(
            f"address 的值必须是十六进制字符串，得到 {type(value).__name__}"
        )
    text = value
    if text[:2] in ("0x", "0X"):
        text = text[2:]
    if len(text) != 40 or any(ch not in _HEX_DIGITS for ch in text):
        raise ABIValueError(f"address 的值必须是 40 位十六进制：{value!r}")
    return _word(int(text, 16))


def _encode_dynamic_bytes(data: bytes) -> bytes:
    padding = -len(data) % _WORD
    return _word(len(data)) + data + b"\x00" * padding


def _encode_elementary(abi_type: ElementaryType, value: object) -> bytes:
    kind = abi_type.kind
    if kind == "uint":
        number = _check_int(value, "uint")
        if not 0 <= number < (1 << abi_type.bit_size):
            raise ABIValueError(
                f"uint{abi_type.bit_size} 的值越界：{number}"
            )
        return _word(number)
    if kind == "int":
        number = _check_int(value, "int")
        bound = 1 << (abi_type.bit_size - 1)
        if not -bound <= number < bound:
            raise ABIValueError(
                f"int{abi_type.bit_size} 的值越界：{number}"
            )
        return _word(number % (1 << 256))
    if kind == "address":
        return _encode_address(value)
    if kind == "bool":
        if type(value) is not bool:
            raise ABIValueError(
                f"bool 的值必须是 Python bool，得到 {type(value).__name__}"
            )
        return _word(1 if value else 0)
    if kind == "string":
        if not isinstance(value, str):
            raise ABIValueError(
                f"string 的值必须是 str，得到 {type(value).__name__}"
            )
        return _encode_dynamic_bytes(value.encode("utf-8"))
    if kind == "bytes":
        if abi_type.byte_size is None:
            return _encode_dynamic_bytes(_check_bytes(value, "bytes"))
        data = _check_bytes(value, f"bytes{abi_type.byte_size}")
        if len(data) != abi_type.byte_size:
            raise ABIValueError(
                f"bytes{abi_type.byte_size} 的长度必须是 {abi_type.byte_size}，"
                f"得到 {len(data)}"
            )
        return data + b"\x00" * (_WORD - abi_type.byte_size)
    raise ABIValueError(f"不是合法的 ABI 类型对象：{abi_type!r}")


def _encode_tuple_body(types: list, values: list) -> bytes:
    """按 head/tail 规则编码一组按声明顺序排列的 (类型, 值)。"""
    heads = []
    tails = []
    offset = sum(
        _WORD if _is_dynamic(t) else _static_size(t) for t in types
    )
    for abi_type, value in zip(types, values):
        if _is_dynamic(abi_type):
            tail = _encode(abi_type, value)
            heads.append(_word(offset))
            tails.append(tail)
            offset += len(tail)
        else:
            heads.append(_encode(abi_type, value))
    return b"".join(heads + tails)


def _encode(abi_type: ABIType, value: object) -> bytes:
    if isinstance(abi_type, ElementaryType):
        return _encode_elementary(abi_type, value)
    if isinstance(abi_type, ArrayType):
        items = _check_sequence(value, "数组")
        if abi_type.length is None:
            body = _encode_tuple_body(
                [abi_type.element_type] * len(items), items
            )
            return _word(len(items)) + body
        if len(items) != abi_type.length:
            raise ABIValueError(
                f"定长数组长度必须是 {abi_type.length}，得到 {len(items)}"
            )
        return _encode_tuple_body(
            [abi_type.element_type] * abi_type.length, items
        )
    if isinstance(abi_type, TupleType):
        items = _check_sequence(value, "元组")
        if len(items) != len(abi_type.components):
            raise ABIValueError(
                f"元组需要 {len(abi_type.components)} 个组成部分，"
                f"得到 {len(items)}"
            )
        return _encode_tuple_body(list(abi_type.components), items)
    raise ABIValueError(f"不是合法的 ABI 类型对象：{abi_type!r}")


# ---- 解码 ---------------------------------------------------------------


class _Decoder:
    """只读视图；记录读取到达的最远位置以检测尾部残留。"""

    def __init__(self, data: bytes) -> None:
        self._data = data
        self.max_end = 0

    def read(self, offset: int, size: int) -> bytes:
        end = offset + size
        if offset < 0 or end > len(self._data):
            raise ABIValueError(
                f"数据长度不足或偏移越界：读取 [{offset}, {end})，"
                f"数据共 {len(self._data)} 字节"
            )
        if end > self.max_end:
            self.max_end = end
        return self._data[offset:end]

    def read_word(self, offset: int) -> int:
        return int.from_bytes(self.read(offset, _WORD), "big")


def _decode_dynamic_bytes(decoder: _Decoder, offset: int) -> bytes:
    length = decoder.read_word(offset)
    data = decoder.read(offset + _WORD, length)
    padding = -length % _WORD
    if padding and any(decoder.read(offset + _WORD + length, padding)):
        raise ABIValueError("动态字节数据的尾部填充不是零")
    return data


def _decode_elementary(decoder: _Decoder, abi_type: ElementaryType, offset: int):
    kind = abi_type.kind
    if kind == "uint":
        number = decoder.read_word(offset)
        if number >= (1 << abi_type.bit_size):
            raise ABIValueError(
                f"uint{abi_type.bit_size} 的编码数值越界：{number}"
            )
        return number
    if kind == "int":
        number = decoder.read_word(offset)
        bound = 1 << (abi_type.bit_size - 1)
        if number < bound:
            return number
        if number >= (1 << 256) - bound:
            return number - (1 << 256)
        raise ABIValueError(
            f"int{abi_type.bit_size} 的编码不是合法的符号扩展：{number}"
        )
    if kind == "address":
        number = decoder.read_word(offset)
        if number >= (1 << 160):
            raise ABIValueError(f"address 的编码数值越界：{number}")
        return "0x" + number.to_bytes(20, "big").hex()
    if kind == "bool":
        number = decoder.read_word(offset)
        if number == 0:
            return False
        if number == 1:
            return True
        raise ABIValueError(f"非法的布尔字：{number}")
    if kind == "string":
        data = _decode_dynamic_bytes(decoder, offset)
        try:
            return data.decode("utf-8")
        except UnicodeDecodeError as exc:
            raise ABIValueError(f"string 的编码不是合法 UTF-8：{exc}") from exc
    if kind == "bytes":
        if abi_type.byte_size is None:
            return _decode_dynamic_bytes(decoder, offset)
        word = decoder.read(offset, _WORD)
        if any(word[abi_type.byte_size:]):
            raise ABIValueError(
                f"bytes{abi_type.byte_size} 的尾部填充不是零"
            )
        return word[: abi_type.byte_size]
    raise ABIValueError(f"不是合法的 ABI 类型对象：{abi_type!r}")


def _decode_tuple_body(decoder: _Decoder, types: list, base: int) -> list:
    """解码位于 base 处的一组 head/tail 成员，偏移相对 base。"""
    values = []
    cursor = base
    for abi_type in types:
        if _is_dynamic(abi_type):
            tail_offset = decoder.read_word(cursor)
            values.append(_decode(decoder, abi_type, base + tail_offset))
            cursor += _WORD
        else:
            values.append(_decode(decoder, abi_type, cursor))
            cursor += _static_size(abi_type)
    return values


def _decode(decoder: _Decoder, abi_type: ABIType, offset: int):
    if isinstance(abi_type, ElementaryType):
        return _decode_elementary(decoder, abi_type, offset)
    if isinstance(abi_type, ArrayType):
        element = abi_type.element_type
        if abi_type.length is None:
            length = decoder.read_word(offset)
            base = offset + _WORD
        else:
            length = abi_type.length
            base = offset
        if (
            length > _ZERO_SIZE_ELEMENT_LIMIT
            and not _is_dynamic(element)
            and _static_size(element) == 0
        ):
            raise ABIValueError(f"数组长度异常：{length}")
        items = _decode_tuple_body(decoder, [element] * length, base)
        return list(items)
    if isinstance(abi_type, TupleType):
        return tuple(_decode_tuple_body(decoder, list(abi_type.components), offset))
    raise ABIValueError(f"不是合法的 ABI 类型对象：{abi_type!r}")


# ---- 公开入口 -----------------------------------------------------------


def encode_abi_value(abi_type: ABIType, value: object) -> bytes:
    """把 Python 值按 ABI 类型编码为 bytes。

    值与类型不匹配或类型对象不适用时抛出 :class:`abi_kit.ABIValueError`。
    """
    _check_type(abi_type)
    return _encode_tuple_body([abi_type], [value])


def decode_abi_value(abi_type: ABIType, data: bytes):
    """把完整的 ABI 编码 bytes 按类型还原为 Python 值。

    长度不足、偏移越界、尾部残留、非法布尔字、非法 UTF-8、越界数值
    或类型对象不适用时抛出 :class:`abi_kit.ABIValueError`；
    输入 data 不会被修改。
    """
    _check_type(abi_type)
    if isinstance(data, (bytes, bytearray, memoryview)):
        blob = bytes(data)
    else:
        raise ABIValueError(
            f"编码数据必须是 bytes 类型，得到 {type(data).__name__}"
        )
    decoder = _Decoder(blob)
    values = _decode_tuple_body(decoder, [abi_type], 0)
    if decoder.max_end != len(blob):
        raise ABIValueError(
            f"编码数据存在未消费的尾部：共 {len(blob)} 字节，"
            f"消费到 {decoder.max_end}"
        )
    return values[0]

